session_log = "/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference-2/play/users/u093/system/state/sessions/01a19d93-d587-7179-829d-fbc6cca3b525.jsonl"

with open(session_log, 'r') as f:
    all_lines = [json.loads(line) for line in f.readlines()]

print("Searching for evaluation feedback...")
print("="*60)

found_results = []

for i, entry in enumerate(all_lines):
    entry_type = entry.get('type', '')

    # Check for three specific types of content
    if entry_type == 'custom' or entry_type == 'custom_message':
        content = entry.get('content', '')
        if isinstance(content, str):
            content_lower = content.lower()
            if 'wrong' in content_lower or 'correct' in content_lower or 'stamp' in content_lower or 'correct' in content_lower:
                found_results.append((i, 'custom_message', content[:200]))

    elif entry_type == 'message':
        body = entry.get('message', {})
        if isinstance(body, dict):
            body_text = str(body).lower()
            if 'wrong' in body_text or 'correct' in body_text:
                found_results.append((i, 'message', str(body)[:200]))

if found_results:
    for idx, msg_type, preview in found_results:
        print(f"\nFound at line {idx} (type: {msg_type}):")
        print(preview)
else:
    print("No evaluation results found in session log.")
    print("\nThis means either:")
    print("1. No submission has been made yet")
    print("2. No result feedback has been recorded")
    print("3. The evaluation system hasn't finished processing")

